class Solution {
    public int subarraySum(int[] nums, int k) {
        int n = nums.length;
        int count = 0;

        for (int left = 0; left < n; left++) {
            int sum = 0;
            for (int right = left; right < n; right++) {
                sum += nums[right];      // 增量求和
                if (sum == k) count++;
            }
        }
        return count;
    }
}

class Solution {
    public int subarraySum(int[] nums, int k) {
        int n = nums.length;
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

        int count = 0;
        for (int j = 1; j <= n; j++) {
            for (int i = 0; i < j; i++) {
                // nums[i..j-1] 的和
                if (prefix[j] - prefix[i] == k) count++;
            }
        }
        return count;
    }
}

import java.util.*;

class Solution {
    public int subarraySum(int[] nums, int k) {
        Map<Integer, Integer> map = new HashMap<>();
        map.put(0, 1);   // 空前缀出现一次，保证从下标 0 开始的子数组能被统计

        int prefix = 0, count = 0;
        for (int x : nums) {
            prefix += x;
            // 先查：之前有多少个前缀和等于 prefix - k
            count += map.getOrDefault(prefix - k, 0);
            // 再存：把自己加入历史，顺序不能反
            map.put(prefix, map.getOrDefault(prefix, 0) + 1);
        }
        return count;
    }
}
